// Manual frontend types — types not generated by ts-rs
// Generated types live in $lib/bindings/

import type { ApiTag } from "#lib/bindings/index.ts";
import type { ProjectStatus } from "#lib/bindings/index.ts";
import type { JSONContent } from "@tiptap/core";
import type { TerminalCast } from "#lib/bindings/index.ts";

// Frontend alias
export type TagWithIcon = ApiTag;

// Request types (include `id` for client routing, not present in Rust request structs)
export interface CreateProjectData {
  name: string;
  slug?: string;
  shortDescription: string;
  status: ProjectStatus;
  hidden: boolean;
  private: boolean;
  githubRepo?: string;
  demoUrl?: string;
  tagIds: string[];
  detailContent?: JSONContent | null;
  // Carried through unchanged: updates replace the whole project, so omitting these would clear them.
  projectType?: string;
  terminalCast?: TerminalCast;
  accentColor?: string;
  relatedIds: string[];
}

export interface UpdateProjectData extends CreateProjectData {
  id: string;
}

export interface CreateTagData {
  name: string;
  slug?: string;
  icon?: string;
  color?: string;
}

export interface UpdateTagData extends CreateTagData {
  id: string;
}

// Vestigial — auth is cookie-based, not token-based
export interface AuthSession {
  token: string;
  expiresAt: string;
}
